    # A solid non-background row/column is a divider. Copy the patterned
    # tile from the last row band into the other bands (and across columns).
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != 0]
    # In these tasks the divider color differs from the surrounding field;
    # use any solid row as a boundary, while repeated source pattern is the
    # band containing the non-background marks.
    if not sep_rows:
        return [row[:] for row in grid]
    color = grid[sep_rows[0]][0]
    sep_rows = [r for r,row in enumerate(grid) if all(x == color for x in row)]
    bands=[]; a=0
    for r in sep_rows:
        if a<r: bands.append((a,r))
        a=r+1
    if a<h: bands.append((a,h))
    # If a usable tiled source exists in the bottom band, repeat it in all bands.
    if not bands: return [row[:] for row in grid]
    sb, se = bands[-1]
    source=[row[:] for row in grid[sb:se]]
    out=[row[:] for row in grid]
    for a,b in bands:
        for r in range(a,b):
            out[r]=source[(r-a)%len(source)][:]
    # Solid vertical dividers: the pattern in the rightmost region is propagated left.
    sep_cols=[c for c in range(w) if all(grid[r][c]==color for r in range(h))]
    if sep_cols:
        cb=[]; a=0
        for c in sep_cols:
            if a<c: cb.append((a,c))
            a=c+1
        if a<w: cb.append((a,w))
        if cb:
            c0,c1=cb[-1]
            for r in range(h):
                src=out[r][c0:c1]
                for x,y in cb:
