    h, w = len(grid), len(grid[0])
    # Fill tiled regions by copying the non-background motif found in one cell.
    # Divider color is the most frequent non-background color spanning rows/cols.
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(v == x for row in grid for v in row))
    rowcuts = [r for r,row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg]
    colcuts = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]
    if not rowcuts and not colcuts:
        return [row[:] for row in grid]
    def bands(n, cuts):
        out=[]; a=0
        for x in cuts:
            if a<x: out.append((a,x))
            a=x+1
        if a<n: out.append((a,n))
        return out
    rb, cb = bands(h,rowcuts), bands(w,colcuts)
    # Use first cell's motif, inferred as the non-background portion of it.
    # Entire tile is copied cyclically; background stays transparent.
    out=[row[:] for row in grid]
    for r0,r1 in rb:
        for c0,c1 in cb:
            # find the cell with the greatest number of marked pixels
            cells=[(a,b) for a,b in rb for c,d in cb]
            sr,sc=max(cells,key=lambda z:sum(v!=bg and v not in (rowcuts and grid[rowcuts[0]][0],) for row in grid[z[0]:next((y for y in rb if y[0]>z[0]),(h,))[0]] for v in row)))
            sh=min(r1-r0, h-sr); sw=min(c1-c0,w-sc)
            for r in range(r0,r1):
                for c in range(c0,c1):
                    rr=sr+(r-r0)%sh; cc=sc+(c-c0)%sw
                    if grid[rr][cc] != bg: out[r][c]=grid[rr][cc]
    return out
