    h, w = len(grid), len(grid[0])
    # Full uniform row/column of a color other than the dominant background
    # marks cell boundaries. Repeat the populated cell pattern into empty cells.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    rows = [r for r,row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg]
    cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]
    def spans(n, cuts):
        ans=[]; a=0
        for x in cuts:
            if a < x: ans.append((a,x))
            a=x+1
        if a<n: ans.append((a,n))
        return ans
    rb, cb = spans(h, rows), spans(w, cols)
    if len(rb)*len(cb) < 2: return [row[:] for row in grid]
    # choose the tile containing most non-background pixels
    best=None; score=-1
    for r0,r1 in rb:
        for c0,c1 in cb:
            s=sum(grid[r][c]!=bg for r in range(r0,r1) for c in range(c0,c1))
            if s>score: score=s; best=(r0,r1,c0,c1)
    if not best: return [row[:] for row in grid]
    r0,r1,c0,c1=best; tile=[row[c0:c1] for row in grid[r0:r1]]
    out=[row[:] for row in grid]
    for a,b in rb:
        for x,y in cb:
            for r in range(a,b):
                for c in range(x,y):
                    v=tile[(r-a)%len(tile)][(c-x)%len(tile[0])]
                    if v != bg: out[r][c]=v
    return out
